#include "simp/CodeGenerator.hpp"

#include "simp/Diagnostic.hpp"

#include <sstream>
#include <utility>

namespace simp {

CodeGenerator::CodeGenerator(std::string targetTriple)
    : targetTriple_(std::move(targetTriple)) {}

[[noreturn]] void CodeGenerator::unsupported(const SourceLocation& location,
                                             const std::string& feature) const {
    throw DiagnosticError(location, feature + " is not supported by the current LLVM backend");
}

std::string CodeGenerator::findVariable(const std::string& name,
                                        const SourceLocation& location) const {
    for (auto scope = scopes_.rbegin(); scope != scopes_.rend(); ++scope) {
        const auto found = scope->find(name);
        if (found != scope->end()) {
            return found->second;
        }
    }
    throw DiagnosticError(location, "backend could not resolve variable '" + name + "'");
}

std::string CodeGenerator::emitIntegerExpression(const Expression& expression) {
    if (expression.kind == ExpressionKind::Integer) {
        return expression.value;
    }
    if (expression.kind == ExpressionKind::Identifier) {
        const auto pointer = findVariable(expression.value, expression.location);
        const auto temporary = "%t" + std::to_string(nextTemporary_++);
        instructions_ += "  " + temporary + " = load i32, ptr " + pointer + "\n";
        return temporary;
    }
    if (expression.kind == ExpressionKind::String) {
        unsupported(expression.location, "string expressions");
    }
    if (expression.kind == ExpressionKind::Unary) {
        const auto operand = emitIntegerExpression(*expression.left);
        const auto temporary = "%t" + std::to_string(nextTemporary_++);
        if (expression.value == "+") {
            return operand;
        }
        if (expression.value == "-") {
            instructions_ += "  " + temporary + " = sub i32 0, " + operand + "\n";
            return temporary;
        }
        if (expression.value == "!") {
            instructions_ += "  " + temporary + ".bool = icmp eq i32 " + operand + ", 0\n";
            instructions_ += "  " + temporary + " = zext i1 " + temporary + ".bool to i32\n";
            return temporary;
        }
        unsupported(expression.location, "unary operator '" + expression.value + "'");
    }
    if (expression.kind == ExpressionKind::Binary) {
        const auto left = emitIntegerExpression(*expression.left);
        const auto right = emitIntegerExpression(*expression.right);
        const auto temporary = "%t" + std::to_string(nextTemporary_++);
        const auto& operation = expression.value;
        if (operation == "+" || operation == "-" || operation == "*") {
            const char* instruction = operation == "+" ? "add" : operation == "-" ? "sub" : "mul";
            instructions_ += "  " + temporary + " = " + instruction + " i32 " + left + ", " +
                             right + "\n";
            return temporary;
        }
        if (operation == "/" || operation == "%") {
            const char* instruction = operation == "/" ? "sdiv" : "srem";
            instructions_ += "  " + temporary + " = " + instruction + " i32 " + left + ", " +
                             right + "\n";
            return temporary;
        }

        std::string predicate;
        if (operation == "==") predicate = "eq";
        else if (operation == "!=") predicate = "ne";
        else if (operation == "<") predicate = "slt";
        else if (operation == "<=") predicate = "sle";
        else if (operation == ">") predicate = "sgt";
        else if (operation == ">=") predicate = "sge";
        else unsupported(expression.location, "operator '" + operation + "'");
        instructions_ += "  " + temporary + ".bool = icmp " + predicate + " i32 " + left + ", " +
                         right + "\n";
        instructions_ += "  " + temporary + " = zext i1 " + temporary + ".bool to i32\n";
        return temporary;
    }
    unsupported(expression.location, "expression");
}

void CodeGenerator::emitStatements(const std::vector<Statement>& statements) {
    for (const auto& statement : statements) {
        emitStatement(statement);
    }
}

void CodeGenerator::emitStatement(const Statement& statement) {
    switch (statement.kind) {
    case StatementKind::Declaration: {
        if (statement.declaredType != "int") {
            unsupported(statement.location, "string declarations");
        }
        auto& scope = scopes_.back();
        const auto pointer = "%v" + std::to_string(nextVariable_++);
        scope.emplace(statement.name, pointer);
        instructions_ += "  " + pointer + " = alloca i32\n";
        if (!statement.expressions.empty()) {
            const auto value = emitIntegerExpression(*statement.expressions.front());
            instructions_ += "  store i32 " + value + ", ptr " + pointer + "\n";
        }
        return;
    }
    case StatementKind::Assignment: {
        const auto pointer = findVariable(statement.name, statement.location);
        const auto value = emitIntegerExpression(*statement.expressions.front());
        instructions_ += "  store i32 " + value + ", ptr " + pointer + "\n";
        return;
    }
    case StatementKind::Print: {
        if (statement.expressions.size() != 1 ||
            statement.expressions.front()->kind == ExpressionKind::String) {
            unsupported(statement.location, "print (expected exactly one integer expression)");
        }
        const auto value = emitIntegerExpression(*statement.expressions.front());
        instructions_ += "  %print" + std::to_string(nextTemporary_++) +
                         " = call i32 (ptr, ...) @printf(ptr @.simp.format, i32 " + value + ")\n";
        return;
    }
    case StatementKind::Block:
        scopes_.emplace_back();
        emitStatements(statement.body);
        scopes_.pop_back();
        return;
    case StatementKind::If:
        unsupported(statement.location, "if statements");
    case StatementKind::While:
        unsupported(statement.location, "while statements");
    }
}

std::string CodeGenerator::generate(const Program& program) {
    scopes_.clear();
    scopes_.emplace_back();
    instructions_.clear();
    nextTemporary_ = 0;
    nextVariable_ = 0;
    emitStatements(program.statements);

    std::ostringstream module;
    module << "source_filename = \"simple\"\n"
           << "target triple = \"" << targetTriple_ << "\"\n\n"
           << "@.simp.format = private unnamed_addr constant [4 x i8] c\"%d\\0A\\00\"\n\n"
           << "declare i32 @printf(ptr, ...)\n\n"
           << "define i32 @main() {\n"
           << "entry:\n"
           << instructions_
           << "  ret i32 0\n"
           << "}\n";
    return module.str();
}

} // namespace simp
